"""Compressed reference simulation results for SBML test cases."""

import zlib
import base64

_BLOBS = {
    "case_a": "",
    "case_b": "",
    "case_c": "",
    "case_d": "eNoljTEOgDAMA/e+xYrqUkp5EAMDGwPweuJkOCWXyPJ9XgcevPhKRUVDK9UIQZthDYI2whYIWgfdOgT1d1shPO37QDLDNiQjbOZdabcdifcUKu3zB9zOHCI=",
    "case_e": "eNorycxN1XE21Ak21KngMtAx0DPVMdQx4jLQM0RiGyGxjZHYJkhsUx2IOrA+IN8MjW+OxrdA41ui8A1ReABBxh5O",
}


def get_expected_csv(case_name):
    """Decompress and return the expected CSV text for a given test case."""
    blob = _BLOBS[case_name]
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")
